sys_script_client.script:
function onSubmit() {
   //Type appropriate comment here, and begin script below

   var balanceLeave = g_form.getValue('leave_balance');
   var daysRequested = g_form.getValue('number_of_leave_days');

   if (balanceLeave === '' || daysRequested === '') {
		return true;
   }

   if(balanceLeave <=0 ) {
		var message = "Warning: You are requesting " + daysRequested + 
                      " days, but your available balance is only " + balanceLeave + 
                      " days.\n\nDo you want to submit this request anyway?";

        var userWantsToProceed = confirm(message);

        // 4. If they click "Cancel" (false), stop the submission
        if (!userWantsToProceed) {

			g_form.submitted = false;
            return false; 
        }
   }

   return true;
}
